  legalUpdated: 'अंतिम अद्यतन: {date}',
  legalContact: 'प्रश्न? {email} पर ईमेल करें।',
  legalPrivacyS1Title: '1. स्थानीय-प्रथम, शून्य सर्वर भंडारण',
  legalPrivacyS1Body: 'आपकी सहेजी हुई कॉलेज सूची, पारिवारिक बजट इनपुट, निबंध और गतिविधि ड्राफ्ट 100% आपके अपने डिवाइस के LocalStorage में संग्रहीत हैं। हम कभी भी किसी छात्र — जिसमें नाबालिग शामिल हैं — की व्यक्तिगत जानकारी अपलोड, बेच या साझा नहीं करते।',
  legalPrivacyS2Title: '2. COPPA और FERPA अनुपालन',
  legalPrivacyS2Body: 'StepOne College हाई स्कूल के छात्रों और माता-पिता के लिए बनाया गया है। हम COPPA (13 वर्ष से कम बच्चों की सुरक्षा) और FERPA (शैक्षिक रिकॉर्ड की सुरक्षा) मानकों के अनुरूप छात्र गोपनीयता सर्वोत्तम प्रथाओं का पालन करते हैं।',
  legalPrivacyS3Title: '3. तृतीय-पक्ष एकीकरण',
  legalPrivacyS3Body: 'यदि आप स्वेच्छा से क्लाउड सिंक सक्षम करते हैं या Stripe सदस्यता खरीदते हैं, तो केवल आवश्यक प्रमाणीकरण और बिलिंग डेटा ही प्रेषित होता है — TLS के साथ संचरण में एन्क्रिप्टेड। हम आपकी भुगतान कार्ड जानकारी संग्रहीत नहीं करते।',
  legalPrivacyS4Title: '4. आपके अधिकार और संपर्क',
  legalPrivacyS4Body: 'चूँकि आपका योजना डेटा आपके डिवाइस पर है, आप इसे पूरी तरह नियंत्रित करते हैं। डेटा प्रथाओं के बारे में पूछने या अपना खाता हटाने के लिए आप कभी भी संपर्क कर सकते हैं।',
  legalTermsS1Title: '1. वित्तीय और Net Price अस्वीकरण',
  legalTermsS1Body: 'सभी ट्यूशन, Net Price (जेब-खर्च) अनुमान, सहायता दर, ROI ग्रेड और वेतन सीमाएँ अमेरिकी शिक्षा विभाग के सार्वजनिक डेटा मॉडल (IPEDS / College Scorecard) से प्राप्त होती हैं, केवल योजना संदर्भ के लिए। वास्तविक लागत और सहायता प्रत्येक कॉलेज के आधिकारिक Financial Aid Offer, FAFSA और CSS Profile द्वारा निर्धारित होती है।',
  legalTermsS2Title: '2. प्रवेश और रैंकिंग अस्वीकरण',
  legalTermsS2Body: 'रैंकिंग, स्वीकृति दर और अन्य आँकड़े सार्वजनिक आधिकारिक स्रोतों से आते हैं और केवल सूचना के लिए हैं। ये किसी संस्थान में प्रवेश का वादा या गारंटी नहीं हैं।',
  legalTermsS3Title: '3. शैक्षिक योजना उपकरण',
  legalTermsS3Body: 'StepOne College केवल शैक्षिक मार्गदर्शन प्रदान करता है। यह आधिकारिक प्रवेश परामर्शदाताओं, वित्तीय सहायता कार्यालयों या कानूनी और वित्तीय सलाहकारों की जगह नहीं लेता।',
  legalTermsS4Title: '4. खाता और सदस्यताएँ',
  legalTermsS4Body: 'अपने लॉगिन क्रेडेंशियल सुरक्षित रखने के लिए आप जिम्मेदार हैं। सदस्यताएँ Stripe के माध्यम से बिल होती हैं: मासिक योजना रद्द होने तक नवीनीकृत होती है, और सीज़न पास एकमुश्त भुगतान है।',
  legalSecurityS1Title: '1. एक्टिविटी पॉलिशर और निबंध मार्गदर्शन',
  legalSecurityS1Body: 'एक्टिविटी पॉलिशर के मज़बूत-क्रिया सुझाव और 150-अक्षर छंटाई केवल स्पष्टता और विचार-विमर्श के संदर्भ के लिए हैं। वे निबंध उत्पन्न नहीं करते या उपलब्धियाँ नहीं बनाते।',
  legalSecurityS2Title: '2. आवेदक की जिम्मेदारी',
  legalSecurityS2Body: 'आवेदक Common App, Coalition App और प्रत्येक कॉलेज में जमा की गई गतिविधि सूची और व्यक्तिगत विवरण की सटीकता, प्रामाणिकता और मौलिकता के लिए पूरी तरह जिम्मेदार हैं।',
  legalSecurityS3Title: '3. मौलिकता और कोई स्वचालित जमा नहीं',
  legalSecurityS3Body: 'हम आपकी ओर से निबंध नहीं लिखते या आवेदन स्वचालित रूप से जमा नहीं करते। हमेशा हर जमा की समीक्षा करें और उसे व्यक्तिगत बनाएँ — प्रवेश अखंडता आपकी जिम्मेदारी है।',
