  legalPrivacyS1Body: 'Tu lista corta de universidades, entradas de presupuesto familiar, borradores de ensayos y actividades se guardan 100% en tu propio dispositivo en LocalStorage. Nunca subimos, vendemos ni compartimos información personal de ningún estudiante — incluidos menores.',
