  legalPrivacyS2Body: 'StepOne College está diseñado para estudiantes de secundaria y padres. Seguimos las mejores prácticas de privacidad estudiantil alineadas con COPPA (protección de menores de 13 años) y FERPA (protección de registros educativos).',
  legalPrivacyS3Title: '3. Integraciones de Terceros',
