  legalPrivacyS4Title: '4. Tus Derechos y Contacto',
  legalPrivacyS4Body: 'Como tus datos de planificación viven en tu propio dispositivo, los controlas por completo. Puedes contactarnos en cualquier momento para consultar nuestras prácticas de datos o eliminar tu cuenta.',
  legalTermsS1Title: '1. Descargo Financiero y de Net Price',
