  legalPrivacyS1Title: '1. Lokal zuerst, Null-Server-Speicher',
  legalPrivacyS1Body: 'Deine Hochschul-Shortlist, Familieneingaben zum Budget, Essay- und Aktivitätsentwürfe werden zu 100 % auf deinem eigenen Gerät in LocalStorage gespeichert. Wir laden niemals persönliche Informationen von Schülern hoch, verkaufen oder teilen sie — einschließlich Minderjähriger.',
  legalPrivacyS2Title: '2. COPPA- & FERPA-Konformität',
  legalPrivacyS2Body: 'StepOne College wurde für High-School-Schüler und Eltern entwickelt. Wir folgen Best Practices für Schülerdatenschutz gemäß COPPA (Schutz von Kindern unter 13) und FERPA (Schutz von Bildungsunterlagen).',
  legalPrivacyS3Title: '3. Drittanbieter-Integrationen',
  legalPrivacyS3Body: 'Wenn du freiwillig Cloud-Sync aktivierst oder ein Stripe-Abo kaufst, werden nur die notwendigen Authentifizierungs- und Abrechnungsdaten übertragen — während der Übertragung mit TLS verschlüsselt. Wir speichern keine Kreditkartendaten.',
  legalPrivacyS4Title: '4. Deine Rechte & Kontakt',
  legalPrivacyS4Body: 'Da deine Planungsdaten auf deinem eigenen Gerät liegen, kontrollierst du sie vollständig. Du kannst uns jederzeit kontaktieren, um Fragen zu Datenpraktiken zu klären oder dein Konto zu löschen.',
  legalTermsS1Title: '1. Finanz- & Net-Price-Hinweis',
  legalTermsS1Body: 'Alle Studiengebühren, Net-Price-Schätzungen (Selbstzahler), Förderquoten, ROI-Noten und Gehaltsspannen stammen aus öffentlichen Datenmodellen des US-Bildungsministeriums (IPEDS / College Scorecard) und dienen nur der Planung. Tatsächliche Kosten und Förderungen bestimmt das offizielle Financial Aid Offer der jeweiligen Hochschule, FAFSA und CSS Profile.',
  legalTermsS2Title: '2. Zulassungs- & Ranking-Hinweis',
  legalTermsS2Body: 'Rankings, Zulassungsquoten und weitere Statistiken stammen aus öffentlichen offiziellen Quellen und sind nur informativ. Sie sind kein Versprechen oder Garantie für eine Zulassung.',
  legalTermsS3Title: '3. Bildungsplanungswerkzeug',
  legalTermsS3Body: 'StepOne College bietet nur Bildungsberatung. Es ersetzt keine offiziellen Zulassungsberater, Förderstellen oder Rechts- und Finanzberater.',
  legalTermsS4Title: '4. Konto & Abonnements',
  legalTermsS4Body: 'Du bist für die Sicherheit deiner Anmeldedaten verantwortlich. Abos werden über Stripe abgerechnet: der Monatsplan verlängert sich bis zur Kündigung, der Saison-Pass ist eine Einmalzahlung.',
  legalSecurityS1Title: '1. Activity-Polisher & Essay-Leitfaden',
  legalSecurityS1Body: 'Die Starkverb-Vorschläge und die Kürzung auf 150 Zeichen des Activity-Polishers dienen nur der Klarheit und Ideenfindung. Sie erzeugen keine Essays und erfinden keine Leistungen.',
  legalSecurityS2Title: '2. Verantwortung der Bewerber',
