  legalPrivacyS1Body: 'La tua shortlist universitaria, i dati del budget familiare, le bozze di saggi e attività sono salvati al 100% sul tuo dispositivo in LocalStorage. Non carichiamo, vendiamo né condividiamo mai informazioni personali di studenti — inclusi i minori.',
