  legalPrivacyS1Title: '1. 로컬 우선 · 서버 저장 없음',
  legalPrivacyS1Body: '저장한 대학 후보, 가족 예산 입력, 에세이·활동 초안은 전적으로 귀하의 기기(LocalStorage)에 보관됩니다. 미성년자를 포함한 어떤 학생의 개인 식별 정보도 업로드·판매·공유하지 않습니다.',
  legalPrivacyS2Title: '2. COPPA 및 FERPA 준수',
  legalPrivacyS2Body: 'StepOne College는 고등학생과 학부모를 위해 설계되었습니다. COPPA(13세 미만 보호)와 FERPA(교육 기록 보호) 기준에 부합하는 학생 개인정보 보호 모범 사례를 따릅니다.',
  legalPrivacyS3Title: '3. 제3자 연동',
  legalPrivacyS3Body: '클라우드 동기화를 자발적으로 활성화하거나 Stripe 구독을 구매하는 경우, 필요한 인증·청구 데이터만 TLS로 전송 중 암호화하여 전달합니다. 결제 카드 정보는 저장하지 않습니다.',
  legalPrivacyS4Title: '4. 귀하의 권리와 연락처',
  legalPrivacyS4Body: '계획 데이터는 귀하의 기기에 저장되므로 완전히 통제할 수 있습니다. 데이터 관행에 대한 문의나 계정 삭제는 언제든 연락해 주세요.',
  legalTermsS1Title: '1. 재무 및 Net Price 면책 조항',
  legalTermsS1Body: '모든 등록금, Net Price(본인 부담) 추정, 지원 비율, ROI 등급, 초봉 범위는 미국 교육부 공개 데이터 모델(IPEDS / College Scorecard)에 기반한 참고용입니다. 실제 비용과 지원은 각 대학의 공식 Financial Aid Offer, FAFSA, CSS Profile에 따라 결정됩니다.',
  legalTermsS2Title: '2. 입시 및 랭킹 면책 조항',
  legalTermsS2Body: '랭킹, 합격률 및 기타 통계는 공개 공식 출처에서 제공되는 정보 참고용입니다. 어떤 기관의 입학을 약속하거나 보장하지 않습니다.',
  legalTermsS3Title: '3. 교육 계획 도구',
  legalTermsS3Body: 'StepOne College는 교육적 안내만 제공합니다. 공식 입학 상담사, 재정 지원 사무소, 법률·재무 자문가를 대체하지 않습니다.',
  legalTermsS4Title: '4. 계정 및 구독',
  legalTermsS4Body: '로그인 자격 증명을 안전하게 관리할 책임은 귀하에게 있습니다. 구독은 Stripe를 통해 청구됩니다. 월간 플랜은 해지 시까지 갱신되며 시즌 패스는 일시불입니다.',
  legalSecurityS1Title: '1. 활동 다듬기 및 에세이 안내',
  legalSecurityS1Body: '활동 다듬기 도구의 강한 동사 제안과 150자 압축은 명확성과 브레인스토밍 참고용으로만 제공됩니다. 에세이를 생성하거나 성과를 창작하지 않습니다.',
  legalSecurityS2Title: '2. 지원자 책임',
  legalSecurityS2Body: '지원자는 Common App, Coalition App 및 각 대학에 제출하는 활동 목록과 개인 진술의 정확성, 진정성, 독창성에 대해 전적인 책임을 집니다.',
  legalSecurityS3Title: '3. 독창성 보장 및 자동 제출 금지',
  legalSecurityS3Body: '우리는 귀하를 대신해 에세이를 작성하거나 지원서를 자동 제출하지 않습니다. 제출 전 항상 검토하고 개인화하세요 — 입시 진실성은 귀하의 책임입니다.',
