  legalPrivacyS1Title: '1. تخزين محلي، صفر خوادم',
  legalPrivacyS1Body: 'قائمتك الجامعية ومدخلات ميزانية الأسرة ومسودات المقالات والأنشطة محفوظة 100% على جهازك في LocalStorage. لا نرفع أو نبيع أو نشارك أبدًا المعلومات الشخصية لأي طالب — بما في ذلك القُصّر.',
  legalPrivacyS2Title: '2. الامتثال لـ COPPA و FERPA',
  legalPrivacyS2Body: 'صُمم StepOne College لطلاب المدارس الثانوية وأولياء الأمور. نتبع أفضل ممارسات خصوصية الطلاب المتوافقة مع COPPA (حماية الأطفال دون 13 عامًا) و FERPA (حماية السجلات التعليمية).',
  legalPrivacyS3Title: '3. تكاملات الأطراف الثالثة',
  legalPrivacyS3Body: 'إذا فعّلت طوعًا المزامنة السحابية أو اشتركت عبر Stripe، يتم نقل بيانات المصادقة والفوترة الضرورية فقط — مشفرة أثناء النقل عبر TLS. لا نخزن معلومات بطاقة الدفع الخاصة بك.',
  legalPrivacyS4Title: '4. حقوقك والتواصل',
  legalPrivacyS4Body: 'بما أن بيانات التخطيط لديك على جهازك، فأنت تتحكم بها بالكامل. يمكنك التواصل معنا في أي وقت للاستفسار عن ممارسات البيانات أو حذف حسابك.',
  legalTermsS1Title: '1. إخلاء المسؤولية المالي و Net Price',
  legalTermsS1Body: 'جميع الرسوم الدراسية وتقديرات Net Price (من الجيب) ومعدلات المساعدة ودرجات ROI ونطاقات الرواتب مشتقة من نماذج البيانات العامة لوزارة التعليم الأمريكية (IPEDS / College Scorecard) كمرجع تخطيط فقط. تُحدد التكاليف والمساعدات الفعلية من خلال عرض المساعدات المالية الرسمي لكل جامعة وFAFSA وCSS Profile.',
  legalTermsS2Title: '2. إخلاء مسؤولية القبول والترتيب',
  legalTermsS2Body: 'الترتيبات ومعدلات القبول والإحصاءات الأخرى من مصادر رسمية عامة وهي معلوماتية فقط. لا تُعد وعدًا أو ضمانًا للقبول في أي مؤسسة.',
  legalTermsS3Title: '3. أداة التخطيط التعليمي',
  legalTermsS3Body: 'يوفر StepOne College إرشادات تعليمية فقط. لا يحل محل مستشاري القبول الرسميين أو مكاتب المساعدات المالية أو المستشارين القانونيين والماليين.',
  legalTermsS4Title: '4. الحساب والاشتراكات',
  legalTermsS4Body: 'أنت مسؤول عن الحفاظ على أمان بيانات تسجيل الدخول. تُفوتر الاشتراكات عبر Stripe: تتجدد الخطة الشهرية حتى الإلغاء، وبطاقة الموسم دفعة واحدة.',
  legalSecurityS1Title: '1. مُحسِّن الأنشطة وإرشاد المقالات',
  legalSecurityS1Body: 'اقتراحات الأفعال القوية والاختزال إلى 150 حرفًا من مُحسِّن الأنشطة تُقدَّم فقط كمرجع للوضوح والعصف الذهني. لا تولد مقالات ولا تختلق إنجازات.',
  legalSecurityS2Title: '2. مسؤولية مقدم الطلب',
  legalSecurityS2Body: 'مقدمو الطلبات مسؤولون وحدهم عن دقة وصدق وأصالة قائمة الأنشطة والبيانات الشخصية المقدمة إلى Common App وCoalition App وكل جامعة.',
  legalSecurityS3Title: '3. الأصالة وعدم التقديم التلقائي',
  legalSecurityS3Body: 'لا نكتب مقالات بالنيابة عنك ولا نقدم الطلبات تلقائيًا. راجع وخصص كل تقديم — نزاهة القبول مسؤوليتك.',
